let pages;let slide=0,serviceSlide=0;const $=s=>document.querySelector(s);const engineering=['design','estimates','pto','construction','manufacturing','legal'];const accounting=['plans','calculator','app','clients'];const titles={design:'Проектирование и изыскания',estimates:'Сметные услуги',pto:'ПТО и документация',construction:'Строительство и ремонт',manufacturing:'Металлоконструкции',legal:'Юридическое и тендерное сопровождение',plans:'Услуги и тарифы',calculator:'Расчёт обслуживания',app:'Удалённое обслуживание',clients:'Наши клиенты'};const projectData=[{title:'Изготовление и монтаж РВС-10000',client:'Газпромнефть-ННГ',year:'2022–2023',type:'Резервуары',text:'Изготовление и монтаж вертикального стального резервуара в рамках проекта заказчика.'},{title:'Монтаж технологических трубопроводов',client:'ЛУКОЙЛ — Западная Сибирь',year:'2020–2021',type:'Трубопроводы',text:'Работы по монтажу технологических трубопроводов на Нахимкинском ГП.'},{title:'Монтаж подогревателя сетевой воды',client:'Комсомольская ТЭЦ-3',year:'2022',type:'Энергетика',text:'Монтаж ПСГ-5000-3,5-8 на турбоагрегате Т-180/210-130.'},{title:'Ремонт оборудования котельных цехов',client:'Хабаровские ТЭЦ-1 и ТЭЦ-3',year:'2022',type:'Энергетика',text:'Работы по ремонту вспомогательного оборудования котельных цехов.'}];
const features=[['Инженерное направление','ИНЖЕНЕРИЯ','Проектирование, сметное и ПТО-сопровождение. Строительство, капитальный ремонт и изготовление металлоконструкций. Практический опыт промышленных объектов в основе каждой задачи.','engineering','crystal'],['Бухгалтерское направление','БУХГАЛТЕРИЯ','Бухгалтерский и налоговый учёт, отчётность, зарплата и кадровые задачи. Работа с бухгалтером онлайн и данные вашей компании в личном кабинете 1С:БО.','accounting','flower']];
function header(home=false){$('#header').className=home?'':'inner';$('#header').innerHTML=`<a href="#/" aria-label="Ронеко — главная"><img class="logo" src="assets/logo.png" alt="РОНЕКО"></a><button class="menu" aria-expanded="false">Меню ☰</button><nav aria-label="Основная навигация"><a href="#/about">О компании</a><a href="#/engineering">Инженерия</a><a href="#/accounting">Бухгалтерия</a><a href="#/projects">Проекты</a><a href="#/contacts">Контакты</a></nav>`;$('.menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',open)};}
function footer(){$('#footer').innerHTML=`<div class="footer-grid"><div><h2>На связи с вами</h2><p>Есть задача или вопрос?<br>Расскажите — обсудим решение.</p><button class="round" data-request>Связаться с нами ↗</button></div><div><small>Инженерные услуги</small><a href="#/engineering">АО «Ронеко»</a><a href="#/projects">Опыт команды и проекты ↗</a><a href="#/manufacturing">Производство металлоконструкций</a></div><div><small>Бухгалтерское обслуживание</small><a href="#/accounting">ОЦО «Ронеко»</a><a href="mailto:info@roneco.ru">info@roneco.ru ↗</a><a href="#/app">Личный кабинет и приложение</a></div></div><div class="footer-graphic"><h2>Опыт становится решением</h2><p>Инженерные услуги и сопровождение бизнеса.<br>Обсудим, что нужно вашей компании.</p><div><a class="button" href="#/contacts">Обсудить задачу ↗</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Ронеко</span><span>Инженерия · Бухгалтерия</span></div>`;}
function feature(){let f=features[slide];return `<div class="feature-art"><small>${f[0]}</small><img src="assets/${f[4]}.webp" alt="Объёмная фирменная фигура"></div><div class="feature-text"><h2>${f[1]}</h2><p class="line">${f[2]}</p><a href="#/${f[3]}" class="pill">Узнать больше ↗</a><div class="feature-nav"><button class="round" data-feature="-1" aria-label="Предыдущее направление">←</button><button class="round" data-feature="1" aria-label="Следующее направление">→</button><span class="fine">0${slide+1} / 02</span></div></div>`}
function projectRows(filter='Все'){return projectData.map((p,i)=>({...p,i})).filter(p=>filter==='Все'||p.type===filter).map(p=>`<a class="project-row" href="#/project/${p.i}"><span>${p.client.toUpperCase()}<small>${p.title} · ${p.year}</small></span><span>↗</span></a>`).join('')}
function showcase(){let v=[['Антикоррозийная защита и огнезащита','Подготовка поверхностей и защитная обработка резервуаров, трубопроводов и металлических сооружений.','construction'],['Производство металлоконструкций','Изготовление по рабочей документации, контроль качества и поставка на объект.','manufacturing'],['ПТО и исполнительная документация','Подготовка, ведение и восстановление документов для передачи работ заказчику.','pto']][serviceSlide];return `<div class="showcase-card"><h2>${v[0]}</h2><p>${v[1]}</p><a href="#/${v[2]}">Подробнее ↗</a><div class="showcase-controls"><small>${serviceSlide+1} — 3</small><div><button class="button" data-show="-1" aria-label="Предыдущая услуга">←</button> <button class="button" data-show="1" aria-label="Следующая услуга">→</button></div></div></div>`}
function home(){header(true);$('#main').innerHTML=`<section class="hero"><h1>РОНЕКО</h1><div class="hero-bottom"><div><h2>Опыт в деле.<br>Решения для бизнеса.</h2><p>Инженерные услуги, производство и бухгалтерское сопровождение. От задач на объекте до ежедневной работы вашей компании.</p></div><a href="#directions" aria-label="Перейти к направлениям">↓</a></div></section><div class="wrap"><section class="intro" id="directions"><span class="eyebrow">О КОМПАНИИ</span><h2>Соединяем инженерный опыт<br>и технологии учёта, чтобы помогать<br>вашему бизнесу работать и развиваться.</h2><a class="button" href="#/about">Узнать больше ↗</a></section><section class="feature" id="feature">${feature()}</section><section class="projects-section"><div class="section-side"><h2>Опыт команды<br>на объектах ведущих<br>компаний России</h2><a href="#/projects" class="button">Все проекты ↗</a></div><div><div class="tabs" id="project-tabs">${['Все','Резервуары','Трубопроводы','Энергетика'].map((x,i)=>`<button class="${i?'':'active'}" data-filter="${x}">${x}</button>`).join('')}</div><div id="project-rows">${projectRows()}</div></div></section><section class="showcase" id="showcase">${showcase()}</section><section class="clients"><div class="clients-top"><h2>Промышленные проекты.<br>Практический опыт.</h2><a href="#/projects" class="button">История работ ↗</a></div><div class="wordmarks"><span>ТАТНЕФТЬ</span><span>Газпром нефть</span><span>ЛУКОЙЛ</span><span>ДГК</span><span>МЭИ</span></div><p class="fine">Заказчики и участники проектов из портфолио инженерной команды.</p></section><section class="account-teaser"><div><span class="eyebrow">ОЦО РОНЕКО</span><h2>Бухгалтер<br>в одном чате</h2><p>Документы, вопросы и данные учёта — онлайн. Выберите подходящий формат обслуживания и оставайтесь на связи с бухгалтером.</p><a href="#/accounting" class="button solid">Бухгалтерское обслуживание ↗</a></div><img src="assets/phone.png" alt="Иллюстрация личного кабинета 1С:БО"></section></div>`;}
function inline(s){return s.replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>')}
function linkFor(label){if(/калькулятор|Рассчитать|расчёт|расчет/i.test(label))return 'calculator';if(/проекты|проектов|опыт команды/i.test(label))return 'projects';if(/приложение|удалённ/i.test(label))return 'app';if(/клиенты/i.test(label))return 'clients';if(/тариф|форматы/i.test(label))return 'plans';return ''}
function md(body){let lines=body.split('\n'),out='',skip=false;for(let l of lines){l=l.trim();if(!l)continue;if(l.startsWith('### ')){let h=l.slice(4);skip=/Шаблон|Тексты интерфейса|Дополнительные карточки|Для оценки|Для расчёта/.test(h);if(!skip&&h!=='Форма')out+=`<h2>${h}</h2>`;continue}if(skip||/\[|^Для остальных|^\*\*(Поля|Подсказка|Ошибка|После успешной|Если |Подпись|Вступление|Пояснение|Заголовок результата)/.test(l))continue;if(l.startsWith('**Кнопка в каждой'))continue;if(l.startsWith('**Кноп')){let label=l.split('**').slice(2).join('**').trim();label.split(' / ').forEach(t=>{let link=linkFor(t);out+=link?`<a class="button" href="#/${link}">${t} ↗</a>`:`<button class="button" data-request>${t} ↗</button>`});continue}if(/^\*\*(Заголовок|Финальный заголовок):\*\*/.test(l)){out+=`<h2>${l.replace(/^\*\*.*?:\*\*\s*/,'')}</h2>`;continue}l=l.replace(/^\*\*(Заголовок|Текст|Вступление|Финальный заголовок):\*\*\s*/,'');out+=l.startsWith('- ')?`<p>— ${inline(l.slice(2))}</p>`:`<p>${inline(l)}</p>`}return out}
function lead(page){let b=page.body;const title=(b.match(/\*\*Заголовок:\*\*\s*(.*)/)||[])[1]||page.title;const text=(b.match(/\*\*(?:Текст|Вступление):\*\*\s*(.*)/)||[])[1]||'';const at=b.indexOf('\n### ',b.indexOf('### ')+4);return{title,text,body:at<0?'':b.slice(at)}}
function calc(){return `<h2>Подберём состав обслуживания</h2><p>Укажите параметры бизнеса. Подготовим запрос для индивидуального расчёта — стоимость подтвердит специалист после уточнения объёма работы.</p><form class="calc" id="calc"><label>Организация<select name="company"><option>ООО</option><option>ИП</option><option>Другая форма</option></select></label><label>Формат обслуживания<select name="plan"><option>Комплексный сервис</option><option>Отчётность</option><option>Программа и консультация</option></select></label><label>Количество сотрудников<input name="staff" type="number" min="0" max="100000" value="5" required></label><label>Примерное количество операций в месяц<input name="operations" type="number" min="0" max="1000000" value="50" required></label><div class="checks"><label><input type="checkbox" name="payroll">Расчёт зарплаты</label><label><input type="checkbox" name="hr">Кадровый учёт</label></div><button class="button solid">Сформировать запрос ↗</button><output id="calc-result" aria-live="polite"></output></form>`}
function page(slug,id){const p=pages[slug]||pages.about;header();let l=lead(p),content=md(l.body);let side=engineering.includes(slug)||slug==='engineering'?engineering:accounting.includes(slug)||slug==='accounting'?accounting:['about','projects','contacts'];if(slug==='engineering')content=`<div class="service-links">${engineering.map(k=>`<a href="#/${k}">${titles[k]} ↗</a>`).join('')}</div>`+content;if(slug==='accounting')content=`<img src="assets/1c.png" alt="1С:БухОбслуживание" style="width:135px;margin-bottom:25px"><div class="service-links">${accounting.map(k=>`<a href="#/${k}">${titles[k]} ↗</a>`).join('')}</div>`+content;if(slug==='calculator'){l.title='Стоимость бухгалтерского обслуживания';l.text='Определим состав услуг под задачи вашей компании.';content=calc()}if(slug==='clients')content='<h2>Опыт работы с бизнесом</h2><p>Бухгалтерские задачи зависят от отрасли и организации работы компании. ОЦО «Ронеко» работает с задачами строительства, промышленности и логистики.</p><h2>Обсудим вашу ситуацию</h2><p>Расскажите об операциях компании и текущем формате учёта. Подберём состав обслуживания.</p><button class="button solid" data-request>Обсудить обслуживание ↗</button>';if(slug==='app')content=`<img class="phone" src="assets/phone.png" alt="Иллюстрация приложения">`+content;if(slug==='projects')content=projectRows()+`<h2>Практика, на которой строятся компетенции</h2><p>Портфолио объединяет опыт инженерной команды. Состав и роль участников указаны по доступным материалам проектов.</p>`;if(slug==='project'){let v=projectData[Number(id)]||projectData[0];l={title:v.title,text:v.text};content=`<img src="assets/industry.webp" alt="Промышленные конструкции — иллюстрация направления" style="width:100%;border-radius:8px"><p class="fine">Иллюстрация направления работ</p><h2>О проекте</h2><p><strong>Объект / заказчик:</strong> ${v.client}</p><p><strong>Период:</strong> ${v.year}</p><p><strong>Направление:</strong> ${v.type}</p><p><strong>Статус по исходным материалам:</strong> завершён.</p><h2>Состав работ</h2><p>${v.text}</p><h2>Есть похожая задача?</h2><p>Направьте описание объекта и техническое задание — обсудим состав работ.</p><button class="button solid" data-request>Обсудить проект ↗</button>`}if(slug==='contacts')content=`<h2>Инженерные услуги</h2><p>АО «Ронеко». Проектная подготовка, сметы, ПТО, строительные работы и металлоконструкции.</p><h2>Бухгалтерское обслуживание</h2><p>ОЦО «Ронеко». Учёт, отчётность, зарплата, кадровые задачи и консультации.</p><div class="contact-panel"><h2>Напишите нам</h2><a href="mailto:info@roneco.ru">info@roneco.ru ↗</a><p>Укажите направление, кратко опишите задачу и желаемые сроки. Техническое задание можно приложить к письму.</p><button class="button solid" data-request>Подготовить обращение ↗</button></div>`;$('#main').innerHTML=`<div class="wrap"><section class="pagehead"><div class="breadcrumbs"><a href="#/">Главная</a> / ${p.title}</div><h1>${l.title}</h1><p>${l.text}</p></section><div class="pagebody"><aside class="side-links">${side.map(k=>`<a class="${k===slug?'current':''}" href="#/${k}">${titles[k]||pages[k].title} ↗</a>`).join('')}</aside><article class="article">${content}</article></div></div>`;document.title=`${p.title} — Ронеко`}
function request(message=''){const d=$('#request');d.querySelector('[name=direction]').value=location.hash.match(/accounting|plans|calculator|app|clients/)?'Бухгалтерское обслуживание':'Инженерные услуги';d.querySelector('[name=message]').value=message;d.showModal()}
function route(){const [slug='',id]=location.hash.replace(/^#\/?/,'').split('/');if(slug==='directions')return;slug&&pages[slug]?page(slug,id):home();footer();window.scrollTo(0,0);if(!slug)document.title='Ронеко — инженерные услуги и бухгалтерия';}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-request'))request();if(b.hasAttribute('data-feature')){slide=(slide+Number(b.dataset.feature)+2)%2;$('#feature').innerHTML=feature()}if(b.hasAttribute('data-show')){serviceSlide=(serviceSlide+Number(b.dataset.show)+3)%3;$('#showcase').innerHTML=showcase()}if(b.hasAttribute('data-filter')){$('#project-rows').innerHTML=projectRows(b.dataset.filter);$('#project-tabs').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b))}});
$('#request .close').onclick=()=>$('#request').close();$('#request').addEventListener('click',e=>{if(e.target===$('#request'))$('#request').close()});
document.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='calc'){const summary=`Форма: ${f.get('company')}. Обслуживание: ${f.get('plan')}. Сотрудников: ${f.get('staff')}. Операций в месяц: ${f.get('operations')}. Зарплата: ${f.has('payroll')?'да':'нет'}. Кадровый учёт: ${f.has('hr')?'да':'нет'}.`;$('#calc-result').textContent=summary;request('Прошу рассчитать стоимость. '+summary)}else{const body=`Имя: ${f.get('name')}\nEmail: ${f.get('email')}\nНаправление: ${f.get('direction')}\n\n${f.get('message')}`;location.href='mailto:info@roneco.ru?subject='+encodeURIComponent('Запрос с сайта Ронеко — '+f.get('direction'))+'&body='+encodeURIComponent(body)}});
fetch('content.json').then(r=>r.json()).then(data=>{pages=data;route();window.addEventListener('hashchange',route)}).catch(()=>{$('#main').innerHTML='<p>Не удалось загрузить страницу. Обновите её.</p>'});
